SELECT


WHERE 1 = 1



            AND l.student_id = #{scope.studentId}


            AND s.class_id IN
            #{cid}


            AND 1 = 0




    AND (s.student_no LIKE CONCAT('%', #{q.keyword}, '%')
    OR s.name LIKE CONCAT('%', #{q.keyword}, '%')
    OR l.reason LIKE CONCAT('%', #{q.keyword}, '%'))

AND s.class_id = #{q.classId}
AND l.student_id = #{q.studentId}
AND l.status = #{q.status}
AND l.leave_type = #{q.leaveType}
AND DATE(l.start_date) >= #{q.startDate}
AND DATE(l.start_date) <= #{q.endDate}
ORDER BY l.status ASC, l.create_time DESC

SELECT COUNT(*)

WHERE l.status = 0



            AND l.student_id = #{scope.studentId}


            AND s.class_id IN
            #{cid}


            AND 1 = 0
